import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    book = {}  # id -> dict(side, price, qty, arrival, active)
    counter = 0

    def add_resting(oid, side, price, qty, arrival):
        book[oid] = {'side': side, 'price': price, 'qty': qty, 'arrival': arrival, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, arrival, oid))
        else:
            heapq.heappush(sell_heap, (price, arrival, oid))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active']:
                book[oid]['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        arrival = counter
        counter += 1
        remaining = qty

        opp_heap = sell_heap if side == 'buy' else buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            opp_id = top[2]
            opp = book.get(opp_id)
            if opp is None or not opp['active'] or opp['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            opp_price = opp['price']

            if typ != 'market':
                if side == 'buy' and price < opp_price:
                    break
                if side == 'sell' and price > opp_price:
                    break

            # perform match
            heapq.heappop(opp_heap)
            trade_qty = min(remaining, opp['qty'])

            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp['qty'] -= trade_qty

            if opp['qty'] > 0:
                heapq.heappush(opp_heap, (top[0], top[1], opp_id))
            else:
                opp['active'] = False

        if typ == 'limit' and remaining > 0:
            add_resting(oid, side, price, remaining, arrival)
        # ioc/market remainder discarded; fully filled limit orders never
        # need a book entry since they're not resting and cancel on them
        # should do nothing anyway.

    return trades

